<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageCreatedAtVO;

trait MessageCreatedAtAccessor
{
    private MessageCreatedAtVO $_createdAt;
    public function getCreatedAt(): \DateTimeImmutable
    {
        return $this->_createdAt->value();
    }
    public function createdAt(): MessageCreatedAtVO
    {
        return $this->_createdAt;
    }
    public function isCreatedAtChanged(?self $original = null): bool
    {
        return !$this->_createdAt->equals($original?->_createdAt);
    }
    public function withCreatedAt(MessageCreatedAtVO|\DateTimeImmutable $createdAt): self
    {
        $copy = clone $this;
        $copy->_createdAt = MessageCreatedAtVO::from($createdAt);
        return $copy;
    }
}
